mapper.update:
UPDATE t_account_program_purchase
SET purchase_count = purchase_count + #{amount}, updated_at = NOW()
WHERE program_id = #{programId}
  AND user_id = #{userId}
  AND (#{accountLimit} <= 0 OR purchase_count + #{amount} <= #{accountLimit})

UPDATE t_account_program_purchase
SET purchase_count = purchase_count - #{amount}, updated_at = NOW()
WHERE program_id = #{programId}
  AND user_id = #{userId}
  AND purchase_count >= #{amount}

mapper.select:
SELECT COALESCE(purchase_count, 0)
FROM t_account_program_purchase
WHERE program_id = #{programId}
  AND user_id = #{userId}
